-- ============================================================================
-- V1.53__seed_qa_beauty_care.sql
-- ----------------------------------------------------------------------------
-- 迁移目的：为「AI客服学习知识库」(ai_cs_learned_kb) 灌注「美妆个护」
--           (beauty_care) 一级分类下 5 个二级分类的种子 Q&A 数据。
--
-- 数据规模：5 个二级分类 × 30 条 = 150 条高价值 Q&A
--
-- 二级分类清单：
--   1. beauty_skincare     - 护肤品（面霜/精华/面膜/洗面奶/爽肤水/乳液）
--   2. beauty_makeup       - 化妆品（口红/粉底/眼影/睫毛膏/腮红/BB霜）
--   3. beauty_perfume      - 香水（香氛/淡香水/浓香水/香精/留香）
--   4. beauty_personal_care- 个人护理（洗发水/沐浴露/牙膏/卫生巾/剃须刀）
--   5. beauty_tools        - 美容工具（化妆刷/美容仪/卷发棒/理发器/指甲刀）
--
-- 数据特征：
--   - source_type = 'seed'（种子数据，非对话学习）
--   - review_status = 'approved'（已审核通过，可直接用于检索）
--   - enabled = 1 / vector_indexed = 1 / deleted = 0
--   - learn_batch_id = 'seed-v1.53'（批次标识，便于回溯）
--   - score 范围 70-95，按 Q&A 价值差异化
--   - content_hash = MD5(question + answer)，由 SQL 内联计算，保证唯一性
--
-- 写入策略：
--   通过 JOIN ai_cs_kb_category 按 code 关联 category_id，
--   仅匹配 parent_id IS NOT NULL 的二级分类，避免误绑一级分类。
--
-- 注意事项：
--   - 答复文本中的单引号已用两个单引号转义
--   - 不包含任何手机号、微信号、外链等敏感信息
--   - 美妆类商品答复侧重真伪鉴别、成分安全、肤质适配，体现专业信任感
--   - 本脚本可重复执行（content_hash 唯一约束会阻止重复插入，
--     但建议仅在新建库或首次部署时执行）
-- ============================================================================


-- ============================================================================
-- 1. beauty_skincare（护肤品）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.53', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'beauty_skincare' AS code, '这款保质期到什么时候？别是临期的吧' AS question, '亲，这款批号是EB2401，生产日期2024年1月，未开封保质期3年到2027年1月。您看下瓶底喷码图，清晰可见。我们家临期产品会单独标注"临期特价"，这款还有2年多保质期，放心入。护肤品的保质期很重要，过了保质期成分会失效甚至变质，不能贪便宜买临期的哦~' AS answer, '保质期,批号,临期,生产日期' AS tags, '护肤品保质期与批号查询话术' AS source_summary, 90 AS score
  UNION ALL SELECT 'beauty_skincare', '怎么证明是正品？闲鱼假货太多了', '亲，我们家支持专柜验货，可以提供采购小票（关键信息打码）。您也可以扫码瓶身防伪码查溯源。美妆这块我们做的是长期生意，不会为了一单假货砸了招牌。收到货有任何疑问7天无理由退换，运费我们承担。做美妆5年了，靠的就是口碑，您放心拍下~', '正品,验货,防伪,小票,7天无理由', '护肤品正品验证与售后承诺话术', 92
  UNION ALL SELECT 'beauty_skincare', '我是敏感肌能用吗？用了烂脸你负责？', '亲，理解您的顾虑。这款成分表我发您看下，不含酒精香精防腐剂。但每个人过敏源不同，建议您先在耳后或手腕内侧做48小时测试。如果出现红肿刺痛立即停用并联系我们退货。我们做的是回头客生意，不会坑您。敏感肌选护肤品一定要谨慎，成分越简单越好~', '敏感肌,过敏,测试,成分,退货', '敏感肌适用性与过敏测试话术', 91
  UNION ALL SELECT 'beauty_skincare', '这个和专柜比便宜这么多，是不是二手或者瑕疵品？', '亲，这是海淘免税渠道拿的货，不是二手不是瑕疵。专柜有专柜的运营成本，我们省了门店租金和层层代理费，所以价格能下来。瓶身全新未拆封，您收到可以录开箱视频，有任何问题随时找我。海淘和专柜品质一样，只是渠道不同价格更实惠~', '价格,专柜,海淘,渠道,开箱', '护肤品价格差异解释话术', 87
  UNION ALL SELECT 'beauty_skincare', '批号能查吗？我之前买到过假货批号对不上', '亲，批号EB2401可以在品牌官网或"化妆品监管"APP查到生产信息和备案。您下单我把瓶身批号高清图发您，收到货核对一致再确认收货。我们经得起任何形式的验货，假一赔十。批号是护肤品的"身份证"，学会查批号就不怕买到假货了~', '批号,查询,验货,化妆品监管', '护肤品批号查询与验货话术', 89
  UNION ALL SELECT 'beauty_skincare', '这个套装里的小样是真的吗？不会是掺的假小样吧', '亲，套装里的小样和正装同批进货，批号一致，不是后期掺的。每个小样都有独立包装和批号喷码，您可以逐个核对。我们卖的是品牌官方套装，不是自己拼凑的，这点请您放心。官方套装的小样品质和正装一样，可以放心使用~', '套装,小样,批号,正品,官方', '护肤品套装小样真伪解释话术', 88
  UNION ALL SELECT 'beauty_skincare', '我用了会爆痘吗？之前用同类产品烂脸过', '亲，这款是温和配方不含致痘成分，但每个人肤质不同。建议您前两周隔天使用，建立耐受后再每天用。如果出现爆痘停用一周观察，确实不合适我们支持退货。护肤这事儿急不来，咱们慢慢调理。爆痘不一定是产品问题，也可能是皮肤排毒期，坚持两周观察~', '爆痘,建立耐受,温和配方,退货', '护肤品爆痘风险与建立耐受话术', 86
  UNION ALL SELECT 'beauty_skincare', '这个能去痘印吗？多久见效？没用能退吗', '亲，这款主打的是淡化色素沉积，对新生痘印效果明显，一般4-6周能看到变化。但陈年老痘印需要3个月以上坚持使用。护肤没有立竿见影的，承诺几天见效的反而要警惕。用完一整套觉得没效果，我们支持7天无理由退剩余产品。护肤贵在坚持，配合防晒效果更好~', '痘印,见效周期,退货,坚持使用', '护肤品功效承诺与退货话术', 85
  UNION ALL SELECT 'beauty_skincare', '孕妇能用吗？我现在怀着宝宝不敢乱用', '亲，恭喜您！这款成分表我帮您查过了，不含维A酸、水杨酸、对苯二酚等孕妇慎用成分。但每个人孕期反应不同，建议您把成分表发给产科医生确认一下再下单，咱们稳妥起见。宝宝和您都重要，孕期护肤越简单越好，基础保湿就够了~', '孕妇,慎用成分,医生确认,安全', '孕妇护肤品安全性话术', 93
  UNION ALL SELECT 'beauty_skincare', '这个批号怎么读？我看不懂', '亲，EB2401解读：EB是工厂代码，24是2024年，01是1月。也就是2024年1月生产。不同品牌批号规则不一样，您把品牌和批号发我，我帮您解读。或者下载"化妆品监管"APP扫码查询，最准确。学会看批号就不怕买到过期或者临期产品了~', '批号,解读,工厂代码,化妆品监管', '护肤品批号解读教学话术', 84
  UNION ALL SELECT 'beauty_skincare', '我是干性皮肤，这款面霜够滋润吗？冬天用会不会干', '亲，这款面霜主打深层保湿，含玻尿酸和神经酰胺，干皮冬天用完全够滋润。我本人也是干皮，冬天用这款一天下来不紧绷。如果您皮肤特别干，建议搭配同系列精华和爽肤水，锁水效果翻倍。干皮护肤关键是补水+锁水，面霜是最后一步不能省~', '干性皮肤,面霜,滋润,冬天,玻尿酸', '干性皮肤面霜选择与保湿话术', 87
  UNION ALL SELECT 'beauty_skincare', '精华和面霜的使用顺序是什么？先用哪个', '亲，护肤顺序是：洗面奶→爽肤水→精华→乳液/面霜→防晒（白天）。精华在爽肤水之后面霜之前，因为精华分子小要先吸收，面霜是用来锁水的。用反了面霜会阻挡精华吸收。简单记就是"从稀到稠"，质地越稀的越先用。正确的顺序护肤效果才能最大化~', '使用顺序,精华,面霜,护肤步骤', '护肤品使用顺序教学话术', 88
  UNION ALL SELECT 'beauty_skincare', '开封后能用多久？PAO标志怎么看', '亲，开封后保质期看瓶身的PAO标志，就是那个开盖小罐子图标，里面写12M就是开封后12个月内用完，6M就是6个月。这款是12M，开封后一年内用完就行。开封后产品接触空气会氧化，超过PAO期限效果会下降甚至变质。建议开封后在瓶底贴个日期标签提醒自己~', '开封,PAO,保质期,标志', '护肤品开封后保质期与PAO说明', 86
  UNION ALL SELECT 'beauty_skincare', '这款精华液含烟酰胺吗？会不会刺痛', '亲，这款精华含5%烟酰胺，浓度适中不会刺痛。烟酰胺是美白淡斑的好成分，但第一次用建议从低浓度开始建立耐受。如果您没用过烟酰胺，建议先隔天用，两周后没有不适应再每天用。如果出现刺痛泛红停用一周再试。我们这款浓度温和，大部分人都耐受~', '烟酰胺,精华,刺痛,建立耐受', '烟酰胺精华使用与耐受话术', 87
  UNION ALL SELECT 'beauty_skincare', '面膜多久敷一次？天天敷好不好', '亲，面膜不建议天天敷，一周2-3次就够了。天天敷反而会导致皮肤过度水合，破坏皮肤屏障，变得敏感。每次敷15-20分钟，不要超过20分钟，敷太久面膜会倒吸皮肤水分。敷完记得涂面霜锁水，不然水分很快蒸发。面膜是加分项不是必需品，基础护肤更重要~', '面膜,频率,天天敷,过度水合', '面膜使用频率与正确敷法话术', 88
  UNION ALL SELECT 'beauty_skincare', '洗面奶是氨基酸的还是皂基的？适合什么肤质', '亲，这款是氨基酸洗面奶，温和不刺激，适合所有肤质包括敏感肌。皂基洗面奶清洁力强但刺激，适合大油皮，干皮敏感肌不要用。氨基酸的好处是温和不紧绷，早晚都能用。怎么区分？看成分表靠前的有没有"月桂酸""肉豆蔻酸"等脂肪酸+碱剂，有就是皂基。这款纯氨基酸的，放心用~', '洗面奶,氨基酸,皂基,肤质', '洗面奶氨基酸与皂基区分话术', 89
  UNION ALL SELECT 'beauty_skincare', '爽肤水含酒精吗？敏感肌能用吗', '亲，这款爽肤水不含酒精，成分表我发您看下。含酒精的爽肤水用起来清凉收敛，但敏感肌用了会刺痛泛红。这款用的是植物提取物，温和不刺激，敏感肌放心用。怎么判断含不含酒精？成分表里写"乙醇""变性乙醇"的就是含酒精，排越前含量越高。这款无酒精，您放心~', '爽肤水,酒精,敏感肌,成分', '爽肤水酒精含量与敏感肌话术', 87
  UNION ALL SELECT 'beauty_skincare', '乳液会不会太油腻？夏天能用吗', '亲，这款乳液是轻薄质地的，不油腻，夏天用完全OK。它用的是水包油配方，抹开像水一样清爽，吸收快不黏腻。如果是特别油的皮肤，夏天可以只用爽肤水+精华，跳过乳液。干皮一年四季都要用乳液锁水。这款质地清爽，油皮夏天用也不闷痘，您放心~', '乳液,油腻,夏天,清爽', '乳液质地与夏季使用话术', 84
  UNION ALL SELECT 'beauty_skincare', '换季皮肤不稳定能用这款吗？泛红起皮', '亲，换季皮肤不稳定建议用温和修复类产品，这款含神经酰胺和积雪草提取物，有修复屏障的作用，换季用很合适。换季泛红起皮是屏障受损的表现，要用温和的护肤品，停用美白抗老等功效型产品。这款无香精无酒精，温和修复，换季期用能帮助皮肤稳定。我换季也在用，效果不错~', '换季,泛红,修复,屏障,神经酰胺', '换季护肤与屏障修复话术', 88
  UNION ALL SELECT 'beauty_skincare', '美白精华真的能美白吗？多久见效', '亲，美白精华能淡化色素提亮肤色，但不是几天就能见效的，一般要4-8周坚持使用才能看到变化。美白的关键是：精华+防晒，不防晒用再贵的美白精华都没用。这款含VC和烟酰胺，是经典美白组合。白天一定要涂防晒，不然紫外线会让色斑加深。坚持用+防晒，2个月就能看到肤色均匀透亮~', '美白,精华,见效,防晒,VC', '美白精华功效与防晒话术', 89
  UNION ALL SELECT 'beauty_skincare', '抗老面霜适合多大年龄用？25岁开始用会不会太早', '亲，抗老没有绝对的年龄界限，25岁开始用不早。肌肤胶原蛋白从25岁开始流失，早抗老早受益。这款是初抗老面霜，含胜肽和玻色因，适合25-35岁轻熟肌。如果您是35以上，建议选抗皱效果更强的含视黄醇的产品。25岁用这款刚好，预防大于修复，早保养十年后您会感谢自己~', '抗老,面霜,年龄,25岁,胜肽', '抗老面霜适用年龄话术', 87
  UNION ALL SELECT 'beauty_skincare', '保湿效果能持续多久？冬天一整天不涂会干吗', '亲，这款保湿效果能持续8-10小时，冬天在空调房一天下来不会干。它含透明质酸和角鲨烷，能深层补水+锁水。但如果您在特别干燥的环境（北方冬天暖气房），建议中午补涂一次或者用保湿喷雾。护肤不是一劳永逸的，环境干燥的时候要加强保湿。这款日常用完全够，您放心~', '保湿,持续,冬天,透明质酸', '保湿持久度与冬季护理话术', 85
  UNION ALL SELECT 'beauty_skincare', '用了过敏能退货吗？脸上起红疹了', '亲，过敏了先停用，拍照发给我，我们支持7天无理由退货。过敏不一定是产品质量问题，可能是您对某个成分不耐受。建议您去医院做个过敏源检测，避开过敏成分。退货时把产品寄回来，运费我们承担。脸上起红疹严重的建议看皮肤科，不要自己乱涂药膏。我们做的是长期生意，不会因为一单退货为难您~', '过敏,退货,红疹,过敏源', '护肤品过敏退货处理话术', 90
  UNION ALL SELECT 'beauty_skincare', '海淘的和国专柜的有什么区别？成分一样吗', '亲，海淘版和国内专柜版成分是一样的，都是同一条生产线出来的。区别在于：海淘版是外文包装没有中文标签，专柜版有中文标签和备案号。功效完全一样，就是渠道不同。海淘版因为没有关税和代理费，价格便宜30%-50%。您如果不介意没有中文标签，海淘版性价比更高~', '海淘,专柜,区别,成分,性价比', '海淘与专柜版护肤品对比话术', 86
  UNION ALL SELECT 'beauty_skincare', '护肤品怎么储存？要放冰箱吗', '亲，大部分护肤品常温阴凉处存放就行，不需要放冰箱。避免阳光直射和高温（比如不要放浴室暖气旁）。含VC、视黄醇等活性成分的产品可以放冰箱延长活性，但不要反复冷热交替。护肤品放冰箱要单独放，不要和食物混放。开封后尽快用完，放久了活性成分会失效~', '储存,冰箱,阴凉,活性成分', '护肤品储存与保鲜话术', 83
  UNION ALL SELECT 'beauty_skincare', '这款能和别的牌子混用吗？会不会冲突', '亲，不同品牌的护肤品可以混用，但要注意成分不要冲突。比如烟酰胺不要和高浓度VC同时用（会失效），视黄醇不要和酸类同时用（会刺激）。基础保湿类的混用没问题，功效型的要注意搭配。建议您把在用的产品发我，我帮您看下能不能搭配。护肤不是非得用一整套，适合自己最重要~', '混用,品牌,搭配,成分冲突', '护肤品跨品牌混用话术', 86
  UNION ALL SELECT 'beauty_skincare', '男士能用这款护肤品吗？男女护肤品有区别吗', '亲，护肤品不分男女，看肤质就行。男士一般偏油皮，这款清爽型乳液男士用完全OK。男女护肤品区别主要在香型和包装，成分上大同小异。男士护肤不用太复杂：洗面奶+爽肤水+乳液三步就够了。这款无香型，男士用也不尴尬。我老公也在用这款，他说不油腻很舒服~', '男士,护肤,男女,油皮,无香', '男士护肤品适用性话术', 84
  UNION ALL SELECT 'beauty_skincare', '学生党适合用这款吗？性价比怎么样', '亲，这款性价比很高，适合学生党。一瓶50ml能用3-4个月，算下来一天几毛钱。学生党护肤不用追求大牌，成分好、适合自己的才是最好的。这款核心成分是玻尿酸+神经酰胺，和几百块的大牌成分差不多。省下的钱买点好吃的，皮肤好心情也好。学生时代养成护肤习惯，以后皮肤会感谢您~', '学生党,性价比,平价,玻尿酸', '学生党护肤品性价比话术', 85
  UNION ALL SELECT 'beauty_skincare', '假货和正品包装上有什么区别？怎么一眼看出', '亲，假货和正品包装区别主要看几个点：1.瓶身工艺——正品喷码清晰，假货模糊有毛边；2.瓶盖——正品瓶盖精密不松动，假货松垮有缝隙；3.标签——正品标签贴得端正字体清晰，假货歪斜字体模糊；4.质地气味——正品细腻清香，假货稀薄刺鼻。建议您收货后和专柜比对，有疑问随时找我~', '假货,正品,包装,鉴别,工艺', '护肤品真假包装鉴别话术', 91
  UNION ALL SELECT 'beauty_skincare', '用了一段时间没效果是怎么回事？是假货吗', '亲，护肤品没效果不一定是假货，可能有几个原因：1.肤质不匹配——油皮用了干皮的产品当然没效果；2.用法不对——精华在面霜后面用等于白搭；3.时间不够——大多数产品要4-8周才能看到效果；4.没防晒——不防晒用美白抗老都白搭。建议您把在用的产品和用法发我，我帮您分析。如果确认是假货，我们假一赔十~', '没效果,假货,肤质,用法,防晒', '护肤品无效原因分析话术', 88
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 2. beauty_makeup（化妆品）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.53', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'beauty_makeup' AS code, '这个色号适合黄黑皮吗？买错色号就废了' AS question, '亲，这款#02自然色适合偏黄肤色，#03适合小麦色。您方便的话发张下巴素颜图给我，我帮您看下色号。色号选错未拆封支持7天换货，来回运费我们出，让您买得放心。选粉底色号最好是下颌线试色，不是手背，下颌线颜色最接近脸脖子过渡色~' AS answer, '色号,黄黑皮,换货,试色' AS tags, '化妆品色号匹配与换货话术' AS source_summary, 89 AS score
  UNION ALL SELECT 'beauty_makeup', '持妆多久？会不会半天就脱妆斑驳？', '亲，这款是哑光持妆粉底，正常出油情况下能撑8小时不斑驳。T区出油多的建议搭配定妆粉，能撑10小时以上。我本人混油皮实测带妆10小时下班还ok。具体持久度也看个人肤质和定妆手法。建议妆前做好保湿，定妆用烘焙法，持久度翻倍~', '持妆,脱妆,定妆,持久度', '化妆品持妆时长与定妆技巧话术', 87
  UNION ALL SELECT 'beauty_makeup', '闲鱼的化妆品我都不敢买，怎么证明不是假货？', '亲，理解您的担心。我们家支持专柜比对验货，可以提供采购凭证（打码）。瓶身有防伪码可扫码溯源。更直接的，您收到货去专柜比对质地气味色号，有任何不一致7天无理由退换，运费我们承担。做美妆5年了，靠的就是口碑。假一赔十，您放心拍下~', '正品,验货,专柜比对,防伪', '化妆品正品验证话术', 92
  UNION ALL SELECT 'beauty_makeup', '我是冷白皮用哪个色号？最白的那个会不会太假白', '亲，冷白皮建议#01象牙白，这款是自然白不是死白，不会假白。如果您皮肤特别白可以选#01，偏黄一点选#02。色号这东西建议您先去专柜试色确定后再来下单，我们不介意您比价。选对色号妆感自然，选错就假面，这个不能省步骤~', '冷白皮,色号,假白,试色', '冷白皮色号推荐话术', 86
  UNION ALL SELECT 'beauty_makeup', '这个粉底会不会卡粉？我鼻子起皮严重', '亲，这款含保湿精华，比传统哑光粉底滋润，但起皮严重的部位建议先做好妆前保湿。鼻子起皮可以用爽肤水湿敷3分钟再上妆，效果会好很多。卡粉问题90%是妆前没做好，不是粉底本身问题。上妆用美妆蛋点拍不要涂抹，卡粉会少很多。妆前保湿是关键~', '卡粉,起皮,妆前保湿,湿敷', '化妆品卡粉问题与妆前准备话术', 85
  UNION ALL SELECT 'beauty_makeup', '保质期到什么时候？别是快过期的', '亲，这款批号是A61，生产日期2024年6月，开封后12个月用完（PAO标志12M）。未开封保质期3年到2027年6月。美妆临期我们会单独标注"临期清仓"，这款是新鲜批次，放心入。开封后记得在瓶底贴个日期，提醒自己一年内用完~', '保质期,批号,开封,PAO,临期', '化妆品保质期与PAO标志话术', 86
  UNION ALL SELECT 'beauty_makeup', '敏感肌能用吗？粉底含酒精吗', '亲，这款不含酒精，成分表我发您看下。但敏感肌建议先在耳后或下颌线试色48小时，没有红肿刺痛再全脸使用。卸妆一定要彻底，残妆才是敏感肌的隐形杀手。收到不合适支持7天退换。敏感肌化妆要注意：成分简单、卸妆彻底、不要频繁换产品~', '敏感肌,酒精,试色,卸妆', '敏感肌化妆品适用性话术', 88
  UNION ALL SELECT 'beauty_makeup', '这个口红会沾杯吗？喝水全沾杯子那种', '亲，这款是丝绒哑光质地，沾杯程度比滋润型轻很多，正常喝水轻微沾杯，吃油大的东西会掉色。完全不掉色的口红含重金属反而不好。建议您吃完饭补涂一次，持久度更好。送您一盒卸妆巾试用装。口红沾杯是正常的，完全不掉色反而不健康~', '口红,沾杯,哑光,补涂', '口红沾杯问题与补涂话术', 84
  UNION ALL SELECT 'beauty_makeup', '怎么鉴别真假？我朋友说闲鱼化妆品一半是假的', '亲，这种说法太绝对了。鉴别真假主要看：1.瓶身工艺（假货喷码模糊有毛边）2.气味质地（假货刺鼻稀薄）3.防伪码扫码溯源。我们家支持专柜比对，收到货您可以去专柜验，假一赔十。我们5年老店，靠口碑吃饭。买化妆品一定要找靠谱卖家，不要贪小便宜~', '鉴别,真假,瓶身工艺,防伪码', '化妆品真假鉴别方法话术', 91
  UNION ALL SELECT 'beauty_makeup', '卸妆好卸吗？会不会卸不干净留色素', '亲，这款用眼唇卸妆液敷10秒轻轻擦就能卸干净，不会留色素。不要用洗面奶硬搓，反而伤皮肤。建议搭配同品牌卸妆水，效果最佳。卸妆彻底是护肤第一步，千万别省这一步。眼唇卸妆要用专门的眼唇卸妆液，普通卸妆水卸不干净眼妆~', '卸妆,色素,眼唇卸妆,搭配', '化妆品卸妆难易与搭配话术', 85
  UNION ALL SELECT 'beauty_makeup', '粉底液色号怎么选？买错了能换吗', '亲，粉底色号选下颌线位置的肤色，不要选手背。下颌线是脸和脖子的过渡色，选这个位置最自然。如果两个色号之间纠结，选偏深的那个，浅了会假白深了只是暗一点。买错色号未拆封支持7天换货，运费我们出。建议先去专柜试色再来买，最保险~', '粉底液,色号,换货,下颌线', '粉底液色号选择与换货话术', 88
  UNION ALL SELECT 'beauty_makeup', '眼影会飞粉吗？显色度怎么样', '亲，这款眼影粉质细腻不怎么飞粉，显色度中等偏上。建议用指腹上色比刷子飞粉少，上色前先抖掉多余粉末。这款是大地色系日常通勤百搭，新手也不容易画脏。飞粉的眼影上色前可以先喷定妆喷雾在刷子上，能减少飞粉。这款性价比很高，您放心~', '眼影,飞粉,显色,大地色', '眼影飞粉与显色度话术', 85
  UNION ALL SELECT 'beauty_makeup', '睫毛膏会晕染吗？防水吗', '亲，这款睫毛膏是防水的，出汗出油不容易晕染。但防水意味着难卸，一定要用眼唇卸妆液敷10秒再擦，普通洗面奶卸不掉。如果您是油皮容易晕妆，这款很合适。干皮不防水的也可以。刷的时候从根部Z字形往上刷，纤长又不容易苍蝇腿~', '睫毛膏,晕染,防水,卸妆', '睫毛膏防水与晕染话术', 86
  UNION ALL SELECT 'beauty_makeup', '腮红显色吗？会不会一刷太红', '亲，这款腮红显色度适中，不会一刷就太红，新手友好。建议用松散的腮红刷，少量多次上色，不容易手重。这款是奶茶色系的，显白不挑肤色，日常通勤百搭。腮红画在笑肌最高处往太阳穴方向扫，自然好气色。这款粉质细腻不结块，很好晕染~', '腮红,显色,新手,奶茶色', '腮红显色度与上色技巧话术', 84
  UNION ALL SELECT 'beauty_makeup', 'BB霜遮瑕力怎么样？能遮痘印吗', '亲，这款BB霜遮瑕力中等，能遮泛红和轻微瑕疵，深色痘印需要单独用遮瑕膏。BB霜的好处是护肤+底妆二合一，懒人必备。如果您追求高遮瑕建议用粉底液+遮瑕膏。这款BB霜轻薄自然，适合日常通勤伪素颜。搭配散粉定妆能撑一天，性价比很高~', 'BB霜,遮瑕,痘印,日常', 'BB霜遮瑕力与适用场景话术', 83
  UNION ALL SELECT 'beauty_makeup', '防水吗？夏天出汗会花妆吗', '亲，这款粉底是防水防汗配方的，夏天出汗不容易花妆。但游泳或者大量出汗还是建议用防水粉底液+定妆喷雾+烘焙定妆，三重保险。日常出汗用这款完全够。夏天带妆建议随身带吸油纸和散粉，中午补一下妆更持久。这款防水性不错，夏天用放心~', '防水,出汗,花妆,夏天,定妆', '化妆品防水与夏季定妆话术', 86
  UNION ALL SELECT 'beauty_makeup', '夏天脱妆严重怎么办？有定妆技巧吗', '亲，夏天定妆技巧分享给您：1.妆前用控油妆前乳；2.粉底后用定妆喷雾；3.易出油部位用散粉烘焙法（厚涂散粉等5分钟扫掉）；4.随身带散粉补妆。这样一天下来不太脱妆。这款粉底本身持妆力就不错，配合定妆技巧能撑10小时以上。夏天化妆定妆是关键~', '夏天,脱妆,定妆,烘焙法', '夏季定妆技巧与防脱妆话术', 89
  UNION ALL SELECT 'beauty_makeup', '散粉定妆会不会卡纹？干皮能用吗', '亲，这款散粉是细腻微粒的，不会卡纹。干皮用散粉建议用粉扑按压不要扫，只在T区用少量，两颊不用。或者用定妆喷雾代替散粉，更适合干皮。散粉不是油皮专属，干皮用对方法也不会卡纹。这款散粉粉质很细，干皮用也不拔干，您放心~', '散粉,定妆,卡纹,干皮', '散粉定妆与干皮适用话术', 84
  UNION ALL SELECT 'beauty_makeup', '唇釉持久吗？会不会拔干', '亲，这款唇釉是水光质地的，不拔干但持久度比哑光的稍弱。吃顿饭会掉一些，建议饭后补涂。如果您要持久的选哑光唇釉，但哑光的会偏干。这款水光的滋润显唇纹少，适合嘴唇容易干的。涂唇釉前先涂润唇膏打底，持久又滋润~', '唇釉,持久,拔干,水光', '唇釉持久度与质地话术', 83
  UNION ALL SELECT 'beauty_makeup', '眼线笔防水吗？晕不晕', '亲，这款眼线笔是防水防晕染的，出汗出油不容易晕。画内眼线也不容易花。但油皮建议画完用同色眼影压一下，更持久。卸妆用眼唇卸妆液敷几秒再擦。这款笔头很细，画内眼线和拉眼尾都很顺手。新手也容易上手，画错了用棉签擦掉重画就行~', '眼线笔,防水,晕染,新手', '眼线笔防水与晕染话术', 85
  UNION ALL SELECT 'beauty_makeup', '遮瑕膏会不会干？卡纹吗', '亲，这款遮瑕膏含保湿成分不会太干，但眼下细纹多的部位建议先用眼霜打底再遮瑕，不容易卡纹。遮瑕膏不要厚涂，少量多次叠加效果更自然。这款质地偏润，干皮也能用。深色痘印用橘色遮瑕先校正再上肤色遮瑕，效果更好~', '遮瑕膏,干,卡纹,眼下', '遮瑕膏质地与卡纹话术', 84
  UNION ALL SELECT 'beauty_makeup', '妆前乳有必要用吗？作用是什么', '亲，妆前乳不是必须的，但用了底妆更服帖持久。妆前乳作用：1.填充毛孔平滑肌肤；2.控油或保湿（看类型）；3.修正肤色（绿色泛红、紫色暗沉）。如果您皮肤底子好可以省略，如果毛孔粗大或肤色不均建议用。这款填毛孔的效果不错，后续粉底更服帖~', '妆前乳,作用,毛孔,底妆', '妆前乳作用与必要性话术', 83
  UNION ALL SELECT 'beauty_makeup', '定妆喷雾好用吗？比散粉怎么样', '亲，定妆喷雾和散粉各有优势。散粉控油好适合油皮，定妆喷雾保湿好适合干皮。可以两个一起用：先散粉后喷雾，定妆效果加倍。这款喷雾喷头细腻，喷出来是雾状不会花妆。夏天用定妆喷雾妆感更自然，不会散粉那种哑光感。干皮选喷雾，油皮选散粉~', '定妆喷雾,散粉,对比,定妆', '定妆喷雾与散粉对比话术', 85
  UNION ALL SELECT 'beauty_makeup', '化妆刷掉毛吗？什么材质的', '亲，这套化妆刷是仿生毛的，不容易掉毛。仿生毛比动物毛便宜且好打理，不吸粉好上色。动物毛柔软但贵且需要特殊清洁。这套适合新手，刷子软硬适中，不扎脸。用完定期用刷子清洁剂洗，晾干不容易掉毛。这套性价比很高，新手入门够用了~', '化妆刷,掉毛,仿生毛,新手', '化妆刷材质与掉毛话术', 84
  UNION ALL SELECT 'beauty_makeup', '美妆蛋会吃粉吗？怎么清洗', '亲，美妆蛋多少会吃一点粉，但用对方法可以减少。建议美妆蛋打湿挤干再上妆（微湿状态），吃粉少妆感也更服帖。清洗用美妆蛋清洁剂或者温和洗面奶，揉搓冲干净，阴干不要暴晒。建议1-2周洗一次，不然滋生细菌。美妆蛋3个月换一个，用久了会变硬掉渣~', '美妆蛋,吃粉,清洗,更换', '美妆蛋吃粉与清洁话术', 83
  UNION ALL SELECT 'beauty_makeup', '用了化妆品过敏怎么办？能退吗', '亲，过敏了先停用，拍照发给我，我们支持7天无理由退货，运费我们承担。化妆品过敏可能是对某个成分不耐受，建议去医院做个过敏源测试，以后避开过敏成分。脸上过敏期间不要化妆，精简护肤，用矿泉水喷雾保湿，等皮肤恢复。严重的看皮肤科，不要自己乱涂药膏~', '过敏,退货,停用,过敏源', '化妆品过敏退货处理话术', 90
  UNION ALL SELECT 'beauty_makeup', '和专柜比怎么验货？可以去专柜比对吗', '亲，当然可以！我们鼓励您去专柜验货。您收到货后带去专柜，让专柜导购帮您比对瓶身工艺、喷码、质地、气味、色号，有任何不一致联系我们退货退款。我们做的是正品生意，不怕验。验货是您的权利，我们支持任何形式的验货。假一赔十，5年老店跑不了~', '验货,专柜,比对,退货', '化妆品专柜验货话术', 92
  UNION ALL SELECT 'beauty_makeup', '临期清仓的化妆品能用吗？安全吗', '亲，临期化妆品只要没过保质期就能用，价格便宜很多。但开封后要尽快用完，因为临期产品活性成分可能减弱。临期化妆品适合不介意保质期、想低价试好的产品的人。我们家临期产品会明确标注"临期清仓"，绝不隐瞒。如果您介意可以买新鲜批次的，这款是新鲜批次不是临期~', '临期,清仓,保质期,安全', '临期化妆品安全话术', 83
  UNION ALL SELECT 'beauty_makeup', '套装比单买划算吗？里面都有什么', '亲，套装比单买划算30%-50%。这款套装含：正装粉底液30ml+正装散粉10g+小样妆前乳5ml+小样卸妆水30ml。单买这几样要贵很多。套装里的产品是搭配好的，配合使用效果更好。如果您正想换一套底妆，套装最划算。如果您只需要其中一样，单买也行~', '套装,单买,划算,搭配', '化妆品套装性价比话术', 85
  UNION ALL SELECT 'beauty_makeup', '新手化妆买什么？有推荐吗', '亲，新手化妆入门推荐：1.气垫BB（好上手）；2.眉粉（比眉笔好控制）；3.大地色眼影盘（不容易画脏）；4. mascara睫毛膏；5.润唇膏或有色唇膏。这5样足够日常通勤了。不用一上来买全套，慢慢加。这款气垫BB很适合新手，拍拍就能出门，不会假面。化妆是技术活，多练就好了~', '新手,化妆,推荐,入门,气垫', '新手化妆入门推荐话术', 88
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 3. beauty_perfume（香水）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.53', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'beauty_perfume' AS code, '这个香水是正品吗？闲鱼假香水太多了' AS question, '亲，香水是假货重灾区，理解您的担心。我们家支持专柜验货，可以提供采购凭证（打码）。您收到货可以对比瓶身工艺、喷头细节、液体颜色、前中后调气味，任何不一致7天无理由退换。我们做香水4年，靠的就是真货口碑。假一赔十，您放心拍下~' AS answer, '正品,验货,喷头,前中后调' AS tags, '香水正品验证话术' AS source_summary, 92 AS score
  UNION ALL SELECT 'beauty_perfume', '留香多久？别喷一下半小时就没味了', '亲，这款EDP浓香水，正常喷法留香6-8小时，衣服上能留1-2天。留香时间也看喷的位置和用量，建议喷脉搏点（手腕、耳后、颈侧）不要揉，持久度最佳。EDC淡香水留香2-3小时，EDT淡香3-5小时，您按需选择。留香和香精浓度有关，浓度越高留香越久~', '留香,EDP,脉搏点,喷法', '香水留香时长与喷法话术', 89
  UNION ALL SELECT 'beauty_perfume', '50ml多少钱？比专柜便宜这么多不会是分装吧', '亲，这是原装正品50ml，不是分装不是灌装。瓶身批号、喷头、底标一应俱全，您收到可以和专柜比对。海淘免税渠道拿的货，省了关税和层层代理费，所以价格能下来。分装香水我们会明确标注"分装"，不会以次充好。原装和分装价格差很多，我们不会混着卖~', '原装,分装,批号,海淘,价格', '香水原装与分装区分话术', 90
  UNION ALL SELECT 'beauty_perfume', '前中后调是什么？我怕买回来味道不对', '亲，这款前调是佛手柑柠檬（清新柑橘调），中调是茉莉玫瑰（花香调），后调是麝香檀香（木质调）。前调15分钟内散去，中调是主体持续2-4小时，后调是尾韵留香最久。建议您先去专柜试喷，确定喜欢再来下单。香水味道因人而异，试过再买最保险~', '前中后调,香调,试喷,气味', '香水香调结构解释话术', 88
  UNION ALL SELECT 'beauty_perfume', '这个适合什么场合？上班喷会不会太浓', '亲，这款是清新花果调，适合日常通勤、约会、下午茶。上班建议喷1-2下在脉搏点，淡淡的不会打扰同事。晚宴或正式场合可以喷3-4下，更有存在感。浓烈的东方调不适合上班，咱们这款日常百搭。职场香水原则是"别人不觉得你喷了香水"就对了~', '场合,通勤,花果调,喷量', '香水使用场合推荐话术', 87
  UNION ALL SELECT 'beauty_perfume', 'EDP和EDT有什么区别？哪个划算', '亲，EDP是浓香水（香精15-20%），留香6-8小时，价格稍高；EDT是淡香水（香精5-15%），留香3-5小时，价格亲民。如果追求持久度和层次感选EDP，如果只是日常点缀选EDT就够。这款EDP比EDT贵100但留香翻倍，性价比更高。如果您是上班族建议EDP，一天不用补喷~', 'EDP,EDT,香精浓度,性价比', '香水EDP与EDT区别话术', 88
  UNION ALL SELECT 'beauty_perfume', '保质期到什么时候？香水会过期吗', '亲，香水没有严格保质期，未开封存放3-5年没问题，避开阳光直射和高温即可。这款批号是24A，生产日期2024年1月。开封后建议2年内用完，因为酒精挥发会改变香味。我们家的货都是近1年内的新鲜批次。香水存放要避光阴凉，不要放浴室潮湿环境~', '保质期,批号,存放,开封', '香水保质期与存放话术', 86
  UNION ALL SELECT 'beauty_perfume', '这个分装是真的吗？5ml才几十块', '亲，分装是我们用原装正品分装到5ml滚珠瓶的，不是假货。分装适合试香或出门携带，价格低是因为量少不是品质差。每瓶都标注批号和分装日期，收到您可以和正装比对气味。分装不退不换，建议先确定喜欢正装再回购分装。分装的好处是试错成本低，适合选香~', '分装,滚珠瓶,试香,批号', '香水分装真伪解释话术', 85
  UNION ALL SELECT 'beauty_perfume', '喷头会漏液吗？快递路上洒了怎么办', '亲，我们发货前会用生料带缠绕喷头+锡纸密封+气泡膜包裹，三层防漏。快递路上万一漏液，您拍照发我，立即补发或退款。我们4年发香水几千单，漏液率不到1%，您放心下单。收到货先检查有没有漏液，有漏液拍照发我马上处理，不会让您吃亏~', '喷头,漏液,快递,防漏,补发', '香水快递防漏与售后话术', 88
  UNION ALL SELECT 'beauty_perfume', '孕妇能用香水吗？我现在备孕', '亲，备孕和孕期建议避免使用香水，特别是含麝香、薰衣草、迷迭香成分的。虽然外用影响有限，但稳妥起见孕期不建议使用。如果您特别喜欢，可以等哺乳期后再用，香水存放得当3-5年没问题。宝宝比香味重要，孕期谨慎一点没坏处。这款含麝香成分，孕期不建议~', '孕妇,备孕,麝香,孕期', '孕妇香水使用建议话术', 93
  UNION ALL SELECT 'beauty_perfume', '这个是中性香吗？男女都能用吗', '亲，这款是中性香，男女都能用。中性香一般是木质调或柑橘调，不甜腻不花哨，男女都合适。如果是浓郁花香调就偏女性，烟草皮革调偏男性。这款中性香很适合情侣一起用，或者不确定送男生还是女生的时候选中性最保险。男女都能驾驭，不会违和~', '中性香,男女,木质调,柑橘', '中性香水适用性话术', 86
  UNION ALL SELECT 'beauty_perfume', '夏天用什么香？清新一点的', '亲，夏天建议用清新柑橘调、水生调或者绿茶调，清新不腻。这款佛手柑柠檬调就很适合夏天，喷上清凉感十足。浓烈的东方调和甜腻的花果调夏天用会让人觉得闷。夏天香水建议喷少一点，1-2下够了，出汗多容易和香水混合产生奇怪味道。这款夏天用很清新~', '夏天,清新,柑橘调,水生调', '夏季香水推荐话术', 85
  UNION ALL SELECT 'beauty_perfume', '冬天用什么香？温暖一点的', '亲，冬天建议用温暖的木质调、东方调或者美食调（香草焦糖），给人温暖的感觉。这款檀香木质调冬天用很合适，温暖沉稳。清新的柑橘调冬天用会显得单薄。冬天衣服穿得多，香水可以喷在围巾或者毛衣上，留香更久。冬天用温暖调的香水会让人觉得很有气质~', '冬天,温暖,木质调,东方调', '冬季香水推荐话术', 85
  UNION ALL SELECT 'beauty_perfume', '女生送男生香水选哪款？有推荐吗', '亲，送男生香水建议选中性木质调或者清新的馥奇调，不要太甜太花。这款木质调男女都能用，送男生很合适。或者选经典的海洋调、烟草调，男生一般都喜欢。送香水要注意对方平时用不用香水，如果不用香水的选清淡的入门款。这款包装也好看，送人很体面~', '送男生,香水,木质调,礼物', '送男生香水推荐话术', 87
  UNION ALL SELECT 'beauty_perfume', '送礼买多大容量合适？有包装吗', '亲，送礼建议买50ml，价格适中不寒酸也不浪费。30ml太小显得不够诚意，100ml太贵可能超预算。50ml刚好。我们家有礼盒包装，送礼直接送很好看。也可以帮忙写贺卡，您告诉我要写什么就行。送香水要看对方喜好，不确定的话选中性香最保险~', '送礼,容量,50ml,包装', '香水送礼容量与包装话术', 84
  UNION ALL SELECT 'beauty_perfume', '职场用香水会不会太浓？怎么选', '亲，职场用香水原则是"淡"和"不扰民"。建议选EDT淡香水或者清淡的EDP，喷1-2下在脉搏点就够了。不要喷太多，同事闻到觉得刺鼻就不好了。这款花果调很清淡，职场用合适。浓烈的东方调、甜腻的美食调不适合职场。职场香水让别人"靠近才闻到"就对了~', '职场,香水,清淡,不扰民', '职场香水选择话术', 86
  UNION ALL SELECT 'beauty_perfume', '约会的香？让人印象深刻', '亲，约会用香建议选有记忆点的香水，让对方记住您的味道。这款花香调温柔优雅，约会用很合适。建议喷在耳后和手腕，靠近时淡淡闻到最迷人。不要喷太多，太浓反而让人不适。约会香水要选和平时不一样的，营造新鲜感。这款闻过就忘不了，很适合约会~', '约会,香水,记忆点,花香', '约会香水推荐话术', 87
  UNION ALL SELECT 'beauty_perfume', '香调有哪些分类？怎么选适合自己的', '亲，香调主要分：柑橘调（清新）、花香调（温柔）、果香调（甜美）、绿调（自然）、水生调（清凉）、馥奇调（草本）、木质调（沉稳）、东方调（神秘）、美食调（甜蜜）。选香调看个人气质：温柔选花香，干练选木质，活泼选果香，神秘选东方。建议多试几种找到适合自己的~', '香调,分类,选择,气质', '香调分类与选择话术', 88
  UNION ALL SELECT 'beauty_perfume', '怎么喷留香更久？喷哪里最好', '亲，留香久的喷法：1.喷脉搏点（手腕、耳后、颈侧、手肘内侧），血管浅温度高帮助散发；2.喷后不要揉，揉会破坏香分子；3.喷在衣物上留香更久但要注意会不会留印；4.先涂无香身体乳再喷香水，锁香更久。这款EDP用对方法能留8小时以上~', '留香,喷法,脉搏点,技巧', '香水留香技巧话术', 87
  UNION ALL SELECT 'beauty_perfume', '两款香水能叠加用吗？会冲突吗', '亲，香水可以叠加用，但要选香调相近的。比如柑橘调+花香调叠加会有层次感，但木质调+美食调可能冲突。建议一款做主香喷脉搏点，另一款轻喷衣角做尾韵。叠加用香比较高级，新手建议先用单款。这款单用就很有层次，前中后调变化明显，不需要叠加~', '叠加,香水,冲突,层次', '香水叠加使用话术', 83
  UNION ALL SELECT 'beauty_perfume', '有小样吗？想先试试味道', '亲，有2ml分装小样的，价格很便宜，适合试香。建议您先买小样试味道，喜欢了再买正装。香水味道因人而异，别人说好闻不一定适合您，试过最靠谱。小样能试5-6次，足够判断喜不喜欢了。我们家小样都是原装正品分装的，不是假货，您放心试~', '小样,试香,分装,2ml', '香水小样试香话术', 85
  UNION ALL SELECT 'beauty_perfume', '30ml和50ml哪个划算？能用多久', '亲，50ml比30ml划算，每毫升单价低20%左右。30ml每天用能用3-4个月，50ml能用6-8个月。如果您确定喜欢这款味道，直接买50ml更划算。如果不确定可以先买30ml或者2ml小样试。50ml的性价比最高，我们卖得也最好。您按需要选就行~', '30ml,50ml,划算,能用多久', '香水容量选择与性价比话术', 84
  UNION ALL SELECT 'beauty_perfume', '香水批号怎么看？能查生产日期吗', '亲，香水批号一般印在瓶底或者包装盒上，是字母+数字的组合。不同品牌批号规则不同，您可以告诉我品牌和批号，我帮您查。或者去"化妆品监管"APP或者查批号网站查询。这款批号24A，是2024年1月生产的，很新鲜。买香水看批号能避免买到存放太久的老货~', '批号,生产日期,查询,新鲜', '香水批号查询话术', 83
  UNION ALL SELECT 'beauty_perfume', '香水怎么存放？要避光吗', '亲，香水存放要避光阴凉，避免阳光直射和高温。不要放浴室（温湿度变化大）和暖气旁。最好放在抽屉或者柜子里，温度15-25度最理想。开封后2年内用完最佳，没开封可以放3-5年。不要放冰箱，温度太低会让香水出现沉淀。正确存放香水能用很多年~', '存放,避光,阴凉,温度', '香水存放与保养话术', 84
  UNION ALL SELECT 'beauty_perfume', '香水过期了还能用吗？怎么判断', '亲，香水没有严格过期时间，但存放太久会变质。判断方法：1.看颜色——变深变浑浊可能变质；2.闻味道——发酸发臭就是变质了；3.看沉淀——有沉淀物可能氧化了。正常存放3-5年没问题，变质了就不要用了，可能引起皮肤过敏。这款是新鲜批次，放心用~', '过期,变质,判断,颜色', '香水过期判断话术', 82
  UNION ALL SELECT 'beauty_perfume', '真假香水怎么对比？有什么区别', '亲，真假香水区别：1.瓶身工艺——正品光滑无毛边，假货粗糙有瑕疵；2.喷头——正品喷头精细喷出雾状，假货喷水柱；3.液体颜色——正品清澈，假货可能浑浊；4.气味——正品层次分明留香久，假货单一刺鼻短；5.包装——正品印刷精美，假货模糊。建议收到和专柜比对~', '真假,对比,区别,鉴别', '香水真假对比鉴别话术', 91
  UNION ALL SELECT 'beauty_perfume', '香水的层次感是什么意思', '亲，香水的层次感是指前中后调的变化。前调是你刚喷上的味道（15分钟内），比较清新；中调是15分钟后到2-4小时的味道，是香水的主体；后调是2小时后的尾韵，最持久。好的香水三个阶段变化明显且过渡自然，便宜的香水可能从头到尾一个味道没有变化。这款层次感很明显~', '层次感,前中后调,变化,过渡', '香水层次感解释话术', 86
  UNION ALL SELECT 'beauty_perfume', '春秋适合什么香调', '亲，春秋两季气候温和，大部分香调都适合。春天建议花香调、绿调，生机勃勃的感觉；秋天建议木质调、馥奇调，温暖沉稳的感觉。春秋是换季的时候，可以用一些过渡性的香水，不太浓不太淡。这款花果调春秋用很合适，清新中带着温暖。春秋选香自由度最高，大部分都百搭~', '春秋,香调,花香,木质', '春秋季香水推荐话术', 83
  UNION ALL SELECT 'beauty_perfume', '男生用香水会不会太娘？有推荐吗', '亲，男生用香水不会太娘，反而显得精致有品味。男生选香建议：木质调（沉稳）、馥奇调（清爽）、烟草调（男人味）、海洋调（清新）。避开甜腻的花香调和美食调。这款木质调男生用很合适，温暖有质感。男生用香不要太浓，1-2下够了，淡淡的最有魅力~', '男生,香水,木质调,不会娘', '男生香水推荐话术', 86
  UNION ALL SELECT 'beauty_perfume', '这款香水性价比怎么样？比专柜便宜多少', '亲，这款50ml专柜价800多，我们家卖500出头，便宜了300多。海淘免税渠道拿的货，正品保证。比专柜便宜不是因为假货，是省了关税和渠道费。您可以去专柜验货，假一赔十。香水的成本在于香精浓度和品牌溢价，这款品质不输专柜，价格更实惠。您放心拍下~', '性价比,专柜,便宜,海淘', '香水性价比话术', 87
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 4. beauty_personal_care（个人护理）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.53', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'beauty_personal_care' AS code, '这个洗发水是正品吗？闲鱼假货太多了' AS question, '亲，洗发水也是假货重灾区，理解您。我们家支持商超比对验货，可以提供采购凭证（打码）。瓶身防伪码可扫码溯源，您收到货可以去专柜或屈臣氏比对质地气味。任何不一致7天无理由退换，运费我们承担。洗护用品天天用，选正品很重要，我们5年老店靠口碑吃饭~' AS answer, '正品,验货,防伪,商超比对' AS tags, '个人护理正品验证话术' AS source_summary, 90 AS score
  UNION ALL SELECT 'beauty_personal_care', '这个能治脱发吗？我掉头发快秃了', '亲，这款主打控油蓬松，不能治疗脱发，脱发建议看皮肤科。但控油到位能减少油脂堵塞毛囊，对脂溢性脱发有辅助作用。我本人油头用过，洗完蓬松2天不塌。脱发严重的建议先看医生，洗发水只是辅助。脱发原因很多（遗传、压力、内分泌），要对症治疗~', '脱发,控油,脂溢性,辅助', '洗发水功效边界话术', 88
  UNION ALL SELECT 'beauty_personal_care', '适合油性发质吗？会不会越洗越油', '亲，这款专为油性发质设计，含氨基酸表活无硅油，洗完清爽不假滑。建议搭配同品牌护发素只用发尾，不要接触头皮。油头建议隔天洗一次，频繁洗反而刺激出油。这款控油效果能撑2天，比超市开架货好很多。油头选无硅油氨基酸洗发水就对了，洗完清爽不拔干~', '油性发质,氨基酸,无硅油,控油', '油性发质洗发水推荐话术', 87
  UNION ALL SELECT 'beauty_personal_care', '保质期到什么时候？别是临期的', '亲，这款批号240618，生产日期2024年6月18日，保质期3年到2027年6月。瓶身喷码清晰可见，您收到可以核对。临期清仓产品我们会单独标注，这款是新鲜批次，放心入。洗护用品保质期很重要，过了保质期有效成分会降解还可能滋生细菌~', '保质期,批号,临期,生产日期', '个人护理保质期话术', 85
  UNION ALL SELECT 'beauty_personal_care', '我是敏感头皮会过敏吗？用了头皮痒怎么办', '亲，这款不含硅油硫酸盐，温和配方适合敏感头皮。但每个人过敏源不同，建议您第一次用先在耳后或手臂内侧测试24小时。如果出现头皮痒、红疹立即停用并联系我们退货。我们做的是回头客生意，不会坑您。敏感头皮选洗发水看成分表，避开MIT、CMIT等防腐剂~', '敏感头皮,过敏,测试,退货', '敏感头皮适用性话术', 89
  UNION ALL SELECT 'beauty_personal_care', '这个沐浴露和超市买的有什么区别？贵这么多', '亲，这款含氨基酸表活和烟酰胺，超市开架多是皂基表活。氨基酸更温和不紧绷，烟酰胺有提亮肤色效果。洗完皮肤滑润不假滑，长期用肤色会均匀透亮。贵在成分和工艺，不是智商税。建议您先买小瓶试用，感受下区别。好的沐浴露洗完不紧绷不拔干，差的洗完皮肤干痒~', '沐浴露,氨基酸,烟酰胺,皂基', '沐浴露成分差异话术', 86
  UNION ALL SELECT 'beauty_personal_care', '这个能美白吗？多久见效', '亲，这款含烟酰胺和VC衍生物，有提亮肤色效果，但美白是系统工程，单靠沐浴露不够。建议搭配身体乳和防晒，3个月能看到肤色均匀透亮。承诺几天美白的产品反而要警惕，可能含违禁成分。护肤是长期工程，急不来。沐浴露停留时间短，美白效果有限，主要还是靠身体乳~', '美白,烟酰胺,VC,身体乳,防晒', '个人护理美白功效话术', 85
  UNION ALL SELECT 'beauty_personal_care', '怎么鉴别真假？我之前买到过假货', '亲，鉴别主要看：1.瓶身工艺（假货喷码模糊、瓶盖松）2.质地气味（假货稀薄刺鼻）3.防伪码扫码溯源。我们家支持商超比对，收到货您可以去屈臣氏或专柜比对。假一赔十，5年老店靠口碑吃饭。洗护用品假货成分可能有害，一定不要贪便宜买来路不明的~', '鉴别,真假,瓶身,防伪码', '个人护理真假鉴别话术', 90
  UNION ALL SELECT 'beauty_personal_care', '这个含硅油吗？会不会堵塞毛孔', '亲，这款无硅油配方，含氨基酸表活，不会堵塞毛孔。硅油洗发水洗完假滑但长期堵塞毛囊，无硅油洗完干涩但更健康。建议搭配护发素用发尾，头皮清爽发尾柔顺。这款是sulfate-free配方，敏感头皮也适用。无硅油洗发水刚开始用可能觉得涩，坚持两周就习惯了~', '硅油,氨基酸,sulfate-free,护发素', '洗发水硅油问题话术', 87
  UNION ALL SELECT 'beauty_personal_care', '这个能去屑吗？我头屑很多', '亲，这款含吡啶硫酮锌去屑成分，对真菌性头屑有效。但头屑分干性、油性、真菌性三种，建议您先确定类型。真菌性头屑用这款2-4周见效，干性头屑建议用滋润型洗发水。如果头屑伴随红肿瘙痒，建议看皮肤科，可能是脂溢性皮炎。去屑洗发水建议交替使用，不要长期用同一款~', '去屑,头屑,吡啶硫酮锌,脂溢性', '去屑洗发水适用话术', 88
  UNION ALL SELECT 'beauty_personal_care', '牙膏含氟吗？儿童能用吗', '亲，这款牙膏含氟，防蛀效果好。含氟牙膏成人用完全没问题，但6岁以下儿童建议用儿童专用含氟牙膏（含氟量更低）。6岁以下如果不会吐泡泡沫，建议用无氟牙膏。成人选含氟牙膏能有效防蛀，不用担心氟中毒，正常使用量是安全的。这款含氟量0.14%，成人标准含量~', '牙膏,含氟,儿童,防蛀', '牙膏含氟与儿童适用话术', 85
  UNION ALL SELECT 'beauty_personal_care', '卫生巾材质安全吗？有荧光剂吗', '亲，这款卫生巾是纯棉表层的不含荧光剂，我用紫光灯验过没有荧光反应。材质是医用级棉柔表层，透气不闷热。卫生巾直接接触私密部位，一定要选安全材质的。便宜的劣质卫生巾可能含荧光剂和有害成分，用了容易过敏发炎。这款是大品牌有质检报告，安全放心~', '卫生巾,材质,荧光剂,纯棉', '卫生巾材质安全话术', 91
  UNION ALL SELECT 'beauty_personal_care', '剃须刀锋利吗？会刮伤吗', '亲，这款剃须刀是5层刀片的，锋利但不容易刮伤。5层刀片比3层更贴合面部曲线，刮得更干净。刀片上有润滑条，滑动顺滑不伤皮肤。建议刮之前用热水洗脸软化胡须，涂剃须泡沫，顺着胡须生长方向刮，不容易刮伤。这款是品牌正品，刀片品质好，用着放心~', '剃须刀,锋利,刮伤,刀片', '剃须刀锋利度与安全话术', 84
  UNION ALL SELECT 'beauty_personal_care', '护发素怎么用？能接触头皮吗', '亲，护发素不要接触头皮，只涂发尾和发中。因为护发素含硅油等顺滑成分，接触头皮会堵塞毛囊导致出油脱发。正确用法：洗发后挤干水分，护发素涂耳朵以下的头发，停留2-3分钟冲洗干净。发质特别干的可以叠加发膜每周1-2次。这款护发素滋润不油腻，发尾用很顺滑~', '护发素,用法,头皮,发尾', '护发素正确使用话术', 86
  UNION ALL SELECT 'beauty_personal_care', '洗发多久一次最好？天天洗好不好', '亲，洗头频率看发质：油头隔天洗，干头2-3天洗一次，中性发质2天洗一次。天天洗不一定好，会洗掉头皮天然油脂，导致出油更多或者头皮干燥。但出汗多或者用了造型产品一定要洗。这款洗发水温和，隔天用不会过度清洁。选对洗发水+合理的洗头频率，头皮才会健康~', '洗发,频率,天天洗,发质', '洗发频率与头皮健康话术', 85
  UNION ALL SELECT 'beauty_personal_care', '头皮屑很多怎么办？用什么洗发水', '亲，头屑多先分清类型：1.白色细碎屑+头皮干=干性头屑，用滋润型洗发水；2.黄色油腻屑+头皮油=油性头屑，用控油去屑洗发水；3.大块屑+红肿痒=可能是脂溢性皮炎，看皮肤科。这款含去屑成分，对油性头屑有效。如果是干性头屑用这款可能更干，建议选滋润型的~', '头皮屑,类型,去屑,洗发水', '头皮屑分类与选洗发水话术', 88
  UNION ALL SELECT 'beauty_personal_care', '身体乳保湿持久吗？冬天够用吗', '亲，这款身体乳含玻尿酸和乳木果油，保湿能持续24小时，冬天用完全够。建议洗完澡3分钟内涂身体乳（皮肤还微湿时），锁水效果最好。冬天特别干的部位（手肘、膝盖、脚跟）可以厚涂。这款质地不油腻好吸收，冬天用全身水润不拔干。坚持涂身体乳皮肤会越来越好~', '身体乳,保湿,冬天,玻尿酸', '身体乳保湿与冬季使用话术', 86
  UNION ALL SELECT 'beauty_personal_care', '洗手液杀菌效果怎么样', '亲，这款洗手液含杀菌成分，对常见细菌有效。但日常洗手不需要太强杀菌力，普通洗手液+正确洗手方法（搓20秒）就够了。过度杀菌反而破坏皮肤正常菌群。这款温和不伤手，含保湿成分洗完不干。建议家里用温和洗手液，医院等特殊环境才用强杀菌的~', '洗手液,杀菌,温和,保湿', '洗手液杀菌与温和话术', 82
  UNION ALL SELECT 'beauty_personal_care', '漱口水含酒精吗？能天天用吗', '亲，这款漱口水不含酒精，温和不刺激，能天天用。含酒精的漱口水杀菌力强但刺激口腔黏膜，不建议长期天天用。这款含氟防蛀，饭后漱口30秒吐掉，不要吞咽。漱口水不能代替刷牙，是辅助清洁。正确顺序：先刷牙→牙线→漱口水。这款无酒精不辣嘴，天天用也舒服~', '漱口水,酒精,天天用,含氟', '漱口水酒精与使用频率话术', 84
  UNION ALL SELECT 'beauty_personal_care', '大容量装划算吗？能放多久', '亲，大容量装比小瓶划算30%左右，一家人用很合适。这款500ml大概能用3-4个月。洗护用品保质期一般3年，开封后建议1年内用完。如果一个人用大瓶可能用不完就到期了，建议家庭装一家人用。大瓶要注意开封后盖紧盖子，防止有效成分氧化降解~', '大容量,划算,保质期,家庭装', '大容量洗护用品话术', 83
  UNION ALL SELECT 'beauty_personal_care', '洗护套装比单买划算吗', '亲，洗护套装比单买划算20%-30%。这套含洗发水+护发素+沐浴露，一套解决全身洗护。套装里的产品是搭配好的，成分配合效果更好。如果您正想换洗护品牌，买套装最划算。如果只需要其中一样，单买也行。这套适合油头+油皮，一套搞定全身清洁~', '套装,单买,划算,搭配', '洗护套装性价比话术', 84
  UNION ALL SELECT 'beauty_personal_care', '男士能用这款洗发水吗', '亲，洗发水不分男女，看发质就行。男士一般偏短发油头，这款控油无硅油的男士用完全OK。男女洗发水区别主要在香型和包装，成分大同小异。这款是中性香型，男士用也不尴尬。男士短发用这款控油效果更好，因为短发更容易出油显塌。我老公也在用这款~', '男士,洗发水,男女,控油', '男士洗发水适用话术', 82
  UNION ALL SELECT 'beauty_personal_care', '儿童能用大人的洗发水吗', '亲，不建议儿童用大人的洗发水。儿童头皮比成人娇嫩，大人洗发水成分可能刺激。建议12岁以下用儿童专用洗发水，成分更温和不辣眼。12岁以上可以开始用成人温和款洗发水。这款虽然温和但毕竟是成人配方，不建议儿童用。我店里有儿童洗发水，您需要可以看看~', '儿童,洗发水,大人,温和', '儿童洗发水适用话术', 87
  UNION ALL SELECT 'beauty_personal_care', '用了头皮痒怎么办？能退吗', '亲，头皮痒先停用，可能是对某个成分不耐受。拍照看看头皮有没有红疹，如果有的话可能是过敏。我们支持7天无理由退货，运费我们承担。建议您去医院看下头皮，确认是不是过敏。换洗发水建议先买小瓶试，确认头皮适应了再买大瓶。我们不会因为退货为难您~', '头皮痒,退货,过敏,停用', '洗发水过敏退货话术', 89
  UNION ALL SELECT 'beauty_personal_care', '洗发水怎么储存？会变质吗', '亲，洗发水常温存放就行，避免阳光直射和高温。不要放浴室暖气旁，温度变化大会影响成分。开封后1年内用完最佳，没开封可以放到保质期。洗发水虽然保质期长但开封后接触空气会逐渐降解。用完盖紧盖子防止进水变质。这款保质期到2027年，很新鲜~', '储存,变质,开封,常温', '洗发水储存话术', 81
  UNION ALL SELECT 'beauty_personal_care', '控油效果能持续多久？多久出油', '亲，这款控油效果能持续2天，油头隔天洗一次就行。控油持续时间也看个人出油程度和环境温度，夏天出油多可能1天就油了。建议搭配控油头皮精华，控油效果更持久。这款在控油洗发水里算持久的了，比超市开架货好很多。油头坚持用2-3周，出油会明显减少~', '控油,持续,出油,频率', '控油洗发水效果话术', 85
  UNION ALL SELECT 'beauty_personal_care', '成分安全吗？有有害成分吗', '亲，这款成分很安全，不含硅油、硫酸盐（SLS/SLES）、尼泊金酯防腐剂等争议成分。用的是氨基酸表活，温和不刺激。成分表我发您看下，每个成分都能查到。我们选品的时候会避开有害成分，安全是第一位的。如果您对某个成分过敏可以告诉我，我帮您查这款含不含~', '成分,安全,有害,氨基酸', '洗护用品成分安全话术', 90
  UNION ALL SELECT 'beauty_personal_care', '洗发水正确用法是什么？怎么洗最好', '亲，正确洗头方法：1.先用温水（不要太热）充分打湿头发；2.洗发水在手心搓出泡沫再上头，不要直接挤头皮上；3.用指腹（不是指甲）按摩头皮2-3分钟；4.彻底冲洗干净不要留残留；5.护发素只涂发尾停留2分钟冲洗。这款氨基酸洗发水泡沫丰富，洗完头皮清爽发尾不涩~', '洗发水,用法,正确,指腹', '洗发水正确使用方法话术', 88
  UNION ALL SELECT 'beauty_personal_care', '这款和超市开架货比怎么样', '亲，这款比超市开架货好几个档次。区别：1.表活——这款用氨基酸，超市货多用皂基/SLES，刺激性强；2.成分——这款无硅油无硫酸盐，超市货可能含；3.体验——这款洗完头皮清爽发尾顺滑，超市货洗完要么假滑要么干涩。贵有贵的道理，头皮健康值得投资。建议先买小瓶试~', '对比,超市,开架,氨基酸', '洗护用品与超市货对比话术', 86
  UNION ALL SELECT 'beauty_personal_care', '大瓶装用得完吗？保质期够吗', '亲，这款500ml大瓶，一个人用大概3-4个月，一家人用2个月就用完了。保质期到2027年，开封后1年内用完就行，完全够。如果您一个人用担心用不完，建议买小瓶的。一家人用买大瓶最划算。大瓶要注意用完盖紧，不要进水。这款大瓶比小瓶每毫升便宜30%左右~', '大瓶,用完,保质期,划算', '大瓶洗发水使用话术', 82
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 5. beauty_tools（美容工具）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.53', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'beauty_tools' AS code, '这个美容仪是正品吗？闲鱼假货太多了' AS question, '亲，美容仪单价高，假货确实多，理解您的担心。我们家支持品牌官方售后验货，可以提供采购凭证（打码）。机身序列号可以在品牌官网查询保修。您收到货可以去专柜比对工艺和功能，任何不一致7天无理由退换，运费我们承担。美容仪是贵价品，一定要买正品，假货可能伤皮肤~' AS answer, '正品,美容仪,序列号,官方售后' AS tags, '美容工具正品验证话术' AS source_summary, 92 AS score
  UNION ALL SELECT 'beauty_tools', '这个怎么用？我不会用买了也浪费', '亲，这款美容仪操作简单，开机后选择模式，从下往上从内往外缓慢滑动即可。我们家附赠详细使用视频和说明书，收到货我发您。第一次建议从最低档开始，每次5-10分钟，每周2-3次。有任何使用问题随时问我，包教包会。美容仪不难用，关键是坚持用，用对方法效果才好~', '使用方法,模式,档位,教学视频', '美容仪使用教学话术', 88
  UNION ALL SELECT 'beauty_tools', '清洁麻烦吗？会不会藏污纳垢滋生细菌', '亲，这款探头是医用级不锈钢，用完用湿巾或专用清洁喷雾擦拭即可，不藏污纳垢。建议每周用酒精棉片深度清洁一次。不要水洗机身（电子元件）。配个收纳袋防尘，用2-3年都没问题。清洁不到位确实会滋生细菌，这点很重要。美容仪用完一定要清洁，不然下次用细菌带到脸上~', '清洁,探头,医用不锈钢,收纳', '美容仪清洁维护话术', 86
  UNION ALL SELECT 'beauty_tools', '充电多久？能用多久？别用几次就没电了', '亲，这款充满电需要2小时，满电状态下每天用10分钟能用15-20天。Type-C充电口，充电宝也能充。电池是锂电池，建议电量低于20%再充，不要边充边用，延长电池寿命。我们家发货前会充满电测试，您收到就能用。锂电池不要完全放电再充，随用随充对电池好~', '充电,续航,Type-C,锂电池', '美容仪充电续航话术', 85
  UNION ALL SELECT 'beauty_tools', '这个和专柜比便宜这么多，不会是高仿吧', '亲，这是品牌官方授权渠道拿的货，不是高仿。机身序列号、保修卡、说明书一应俱全，您可以在品牌官网查询保修。专柜有门店租金和人工成本，我们省了这些所以价格能下来。收到货您可以去专柜比对，假一赔十。美容仪高仿很多，一定认准授权渠道和序列号~', '价格,高仿,授权渠道,序列号', '美容工具价格差异话术', 90
  UNION ALL SELECT 'beauty_tools', '这个适合什么部位？能用在眼部吗', '亲，这款适合面部、颈部、下颌线，眼部建议用专用眼部模式（最低档），不要用高档位。眼周皮肤薄，高档位会拉扯皮肤。法令纹、抬头纹、下颌线可以正常用。颈部从下往上，面部从内往外。说明书和视频里有详细演示。眼部用美容仪一定要小心，力度要轻，时间要短~', '部位,眼部,档位,演示', '美容仪适用部位话术', 87
  UNION ALL SELECT 'beauty_tools', '这个真的有效果吗？不会是智商税吧', '亲，美容仪是辅助工具，不是神器和智商税。射频类有紧致淡纹效果（临床数据支持），微电流有提拉消肿效果，LED红光有抗炎修复效果。但需要坚持使用2-3个月才能看到变化，三天打鱼两天晒网肯定没效果。护肤是长期工程，仪器是锦上添花。坚持用配合护肤品效果加倍~', '效果,智商税,射频,微电流,LED', '美容仪功效解释话术', 88
  UNION ALL SELECT 'beauty_tools', '这个噪音大吗？晚上用会不会吵到家人', '亲，这款工作噪音低于50分贝，相当于图书馆环境，晚上用不会吵到家人。射频和LED模式几乎无声，微电流模式有轻微嗡嗡声但很小。建议晚上护肤时用，搭配面膜一起，放松又高效。我们家自用款，每天晚上用很安静。美容仪噪音大小看技术，这款是大品牌技术好噪音低~', '噪音,分贝,射频,微电流', '美容仪噪音问题话术', 83
  UNION ALL SELECT 'beauty_tools', '配件齐全吗？别收到货少东西', '亲，这款标配：主机+充电线+收纳袋+说明书+保修卡。我们家发货前会逐项核对，并录打包视频发给您的。您收到货当快递面核对，少一件补发或退款。我们家做的是口碑生意，不会少件漏件。美容仪配件丢了不好配，收到后收好收纳袋。这款配件齐全，您放心~', '配件,标配,打包视频,核对', '美容仪配件齐全话术', 85
  UNION ALL SELECT 'beauty_tools', '售后怎么样？用坏了找谁修', '亲，这款全国联保1年，机身序列号注册后享受品牌官方售后。我们家额外赠送3个月店铺保修，1年内非人为损坏免费维修。收到货7天内有质量问题支持退换，运费我们承担。美容仪单价高，售后是关键，我们家5年老店跑不了。买美容仪一定要看售后，不然坏了没地方修~', '售后,联保,序列号,店铺保修', '美容仪售后保修话术', 91
  UNION ALL SELECT 'beauty_tools', '化妆刷掉毛吗？什么材质的', '亲，这套化妆刷是仿生毛的，不容易掉毛。仿生毛比动物毛便宜且好打理，不吸粉好上色。动物毛柔软但贵且需要特殊清洁。这套适合新手，刷子软硬适中不扎脸。新刷子前两次用可能掉1-2根浮毛，这是正常的，用几次就不掉了。用完定期清洗晾干，不容易掉毛~', '化妆刷,掉毛,仿生毛,新手', '化妆刷材质与掉毛话术', 84
  UNION ALL SELECT 'beauty_tools', '卷发棒伤头发吗？温度多少合适', '亲，卷发棒多少会有一点伤头发，但控制好温度可以减少损伤。建议温度160-180度，不要超过200度。卷之前一定要涂隔热保护产品，减少热损伤。每次停留不要超过10秒。这款有恒温控制不会过热，负离子功能减少毛躁。用完涂点护发精油修复。卷发棒选有温控和负离子的~', '卷发棒,伤发,温度,负离子', '卷发棒温度与护发话术', 87
  UNION ALL SELECT 'beauty_tools', '理发器噪音大吗？宝宝能用吗', '亲，这款理发器噪音很低，大概40分贝，宝宝不会害怕。刀头是陶瓷的不伤头皮，适合给宝宝理发。建议宝宝睡着后再剪，更配合。这款是静音设计的，电机声音很小。陶瓷刀头比不锈钢的锋利且不发热。给宝宝理发建议选静音陶瓷刀头的，这款很合适~', '理发器,噪音,宝宝,陶瓷刀头', '理发器噪音与宝宝适用话术', 88
  UNION ALL SELECT 'beauty_tools', '指甲刀锋利吗？会不会劈甲', '亲，这款指甲刀是不锈钢的，锋利不劈甲。刀口精密咬合，剪指甲干净利落不毛边。便宜的指甲刀刀口不锋利，剪指甲会劈裂毛边。这款有人性化的指甲收纳仓，剪的指甲不会飞溅。指甲刀看似小事，但差的真的很难用。这款品质不错，用几年都没问题~', '指甲刀,锋利,劈甲,不锈钢', '指甲刀锋利度话术', 82
  UNION ALL SELECT 'beauty_tools', '美容仪有几个档位？怎么选', '亲，这款有5个档位，1档最弱5档最强。新手建议从1档开始，适应后逐渐加档。面部用3-4档够了，颈部和身体可以5档。眼部用1-2档。档位不是越高越好，适合自己的才是最好的。建议第一周用1-2档建立耐受，第二周开始加到3档。这款档位调节很方便，一键切换~', '档位,美容仪,新手,选择', '美容仪档位选择话术', 85
  UNION ALL SELECT 'beauty_tools', '清洁刷能天天用吗？会不会伤皮肤', '亲，清洁刷不建议天天用，一周2-3次够了。天天用会过度清洁破坏皮肤屏障。这款刷毛很软，但毕竟是机械摩擦，用多了皮肤会变薄敏感。建议晚上用，搭配温和洗面奶。用完彻底冲洗晾干，防止滋生细菌。敏感肌和痘痘肌不建议用清洁刷，手洗更安全~', '清洁刷,频率,伤皮肤,屏障', '清洁刷使用频率话术', 86
  UNION ALL SELECT 'beauty_tools', '按摩仪有用吗？是智商税吗', '亲，按摩仪有一定效果，不是智商税。按摩能促进血液循环、放松肌肉、缓解疲劳。这款是EMS微电流按摩，比普通振动按摩深层。用完感觉脸部放松浮肿减轻。但按摩仪是辅助保养，不能替代医美。坚持用配合护肤品效果更好。这款性价比高，适合日常保养用~', '按摩仪,效果,智商税,EMS', '按摩仪功效话术', 83
  UNION ALL SELECT 'beauty_tools', '导入仪真的能促进吸收吗', '亲，导入仪通过微电流/超声波帮助护肤品渗透，确实能促进吸收。但效果不是10倍那么夸张，大概提升30%-50%的吸收率。建议搭配精华液使用，导入效果最明显。这款导入导出双功能，导入用正极促进吸收，导出用负极清洁毛孔。导入仪是护肤加分项，不是必需品~', '导入仪,吸收,微电流,精华', '导入仪功效话术', 84
  UNION ALL SELECT 'beauty_tools', '材质安全吗？接触皮肤会过敏吗', '亲，这款探头是医用级不锈钢和医用硅胶，接触皮肤安全不过敏。不含镍（镍是最常见金属过敏源）。但极少数人对硅胶过敏，建议第一次用在手臂内侧测试24小时。如果出现红肿痒停用并联系我们退货。美容仪材质很重要，便宜的可能用劣质材料导致过敏，这款是大品牌材质达标~', '材质,安全,过敏,医用硅胶', '美容工具材质安全话术', 89
  UNION ALL SELECT 'beauty_tools', '电池能换吗？还是充电的', '亲，这款是充电的，内置锂电池，不需要换电池。Type-C充电口，手机充电器就能充。充电比换电池方便省钱，一次充电用15-20天。锂电池寿命大概500次充放电，用3-5年没问题。电池坏了可以联系售后更换。充电的美容仪比电池的方便，不用老买电池~', '电池,充电,Type-C,锂电池', '美容工具电池话术', 82
  UNION ALL SELECT 'beauty_tools', '旅行携带方便吗？有收纳袋吗', '亲，这款体积不大，比手机大一点，带收纳袋旅行携带很方便。充电是Type-C的，充电宝也能充，旅行不用担心没电。建议放行李箱不要托运，随身携带更安全。收纳袋能装下主机和充电线。这款重量才200g，出门带着不重。出差旅行也能坚持护肤，很方便~', '旅行,携带,收纳袋,便携', '美容工具便携性话术', 81
  UNION ALL SELECT 'beauty_tools', '新手会用吗？操作复杂吗', '亲，这款操作很简单，一键开关+一键切档，新手也会用。附赠详细使用视频和说明书，收到货我发您。第一次用从最低档开始，5分钟就够了。用两次就熟练了。美容仪不是什么高科技，就是个工具，关键是坚持用。有任何问题随时问我，包教包会~', '新手,操作,简单,教学', '美容工具新手操作话术', 84
  UNION ALL SELECT 'beauty_tools', '多久能看到效果？要坚持用吗', '亲，美容仪需要坚持用才能看到效果，一般4-8周能看到变化。射频类紧致淡纹需要8-12周，微电流提拉即时效果但需要坚持维持，LED红光修复需要4-6周。三天打鱼两天晒网肯定没效果，建议每周3-4次坚持3个月。护肤是长期工程，美容仪是锦上添花，坚持才有用~', '效果,周期,坚持,频率', '美容工具效果周期话术', 87
  UNION ALL SELECT 'beauty_tools', '和大牌比怎么样？值得买吗', '亲，这款是平价替代款，功能和大牌差不多但价格便宜一半。核心区别在于：大牌技术更成熟档位更精细，这款基本功能都有够日常用。如果您预算充足买大牌，追求性价比买这款。美容仪原理都差不多（射频/微电流/LED），贵在品牌和技术细节。这款性价比很高，适合入门~', '大牌,对比,性价比,替代', '美容工具与大牌对比话术', 85
  UNION ALL SELECT 'beauty_tools', '配件丢了能单独买吗', '亲，配件可以单独买的，联系我们帮您订购原装配件。建议配件收到后收好收纳袋，不容易丢。常见需要补购的配件：充电线、收纳袋、替换探头。配件价格不贵，几十块钱。美容仪主机不丢就行，配件丢了不影响核心功能。我们5年老店，配件随时可以帮您订~', '配件,丢失,补购,原装', '美容工具配件补购话术', 80
  UNION ALL SELECT 'beauty_tools', '每天用还是隔天用？使用频率', '亲，美容仪不建议每天用，一周3-4次够了。皮肤需要休息恢复，每天用反而过度刺激。射频类一周2-3次，微电流可以每天用（低档），LED红光可以每天用。这款综合模式建议一周3次，每次10分钟。用完做好保湿和防晒。护肤讲究适度，不是越多越好~', '频率,每天,隔天,使用', '美容工具使用频率话术', 86
  UNION ALL SELECT 'beauty_tools', '清洁方便吗？会不会藏污纳垢', '亲，这款清洁很方便。探头是医用级不锈钢，用完用湿巾或酒精棉片擦一下就行。不要水洗机身。建议每周深度清洁一次。配收纳袋防尘。如果用凝胶/精华，用完一定要擦干净，不然残留会滋生细菌。清洁不到位的美容仪比不用还糟糕，把细菌带到脸上。这款好清洁，您放心~', '清洁,方便,藏污纳垢,擦拭', '美容工具清洁话术', 84
  UNION ALL SELECT 'beauty_tools', '保修多久？坏了找谁修', '亲，这款全国联保1年，1年内非人为损坏免费维修。机身序列号注册后享受品牌官方售后。我们家额外赠送3个月店铺保修。收到货7天内有质量问题支持退换。美容仪单价高，一定要看售后。我们家5年老店，售后有保障。坏了联系我，我帮您走售后流程~', '保修,坏了,维修,联保', '美容工具保修话术', 88
  UNION ALL SELECT 'beauty_tools', '这个价格划算吗？比专柜便宜多少', '亲，这款专柜价1200，我们家卖800出头，便宜了400。品牌授权渠道拿的货，正品保证。比专柜便宜是因为省了门店租金和人工成本，不是假货。您可以去专柜验货，假一赔十。美容仪是贵价品，能省400不少了。这款性价比很高，值得入手~', '价格,划算,专柜,便宜', '美容工具性价比话术', 85
  UNION ALL SELECT 'beauty_tools', '送人合适吗？有包装盒吗', '亲，这款有品牌原装礼盒包装，送人很体面。美容仪送闺蜜、送妈妈、送老婆都合适，实用又有心意。我们可以帮忙写贺卡，您告诉我要写什么。送人建议选大品牌的，收礼的人也放心用。这款包装精美，送礼自用都合适。您看中了就拍下，我帮您包装好~', '送人,包装,礼盒,礼物', '美容工具送礼话术', 83
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;
